using System;using System.IO;using System.Linq;using System.Text;using System.Collections;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;using System.Net;using System.Net.Http;using System.Net.Http.Headers;using System.Security.Cryptography;using System.Web.Script.Serialization;using Microsoft.Win32;

[assembly:System.Reflection.AssemblyVersion("1.0.0.0")]
[assembly:System.Reflection.AssemblyProduct("ZNote 系统采集")]
// Optional, per-user Windows Shell integration. No hooks into other applications.
class ZNoteCapture {
 static string Home=AppDomain.CurrentDomain.BaseDirectory,ConfigPath=Path.Combine(Home,"connection.json");
 static JavaScriptSerializer Json=new JavaScriptSerializer();static byte[] Entropy=Encoding.UTF8.GetBytes("ZNote.WindowsCapture.v1");
 static string[] Keys={@"Software\Classes\SystemFileAssociations\image\shell\ZNoteCapture",@"Software\Classes\DesktopBackground\Shell\ZNoteCapture",@"Software\Classes\Directory\Background\shell\ZNoteCapture"};
 internal static string Origin,Token;internal static string Last="";
 static string S(Dictionary<string,object> d,string k){return d.ContainsKey(k)?Convert.ToString(d[k]):"";}
 static void Write(string path,object value){string tmp=path+".tmp";File.WriteAllText(tmp,Json.Serialize(value),Encoding.UTF8);if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}
 static string Normalize(string input){Uri u;if(!Uri.TryCreate(input,UriKind.Absolute,out u)||!(u.Scheme=="http"||u.Scheme=="https")||u.UserInfo!=""||u.AbsolutePath!="/"||u.Query!=""||u.Fragment!="")throw new Exception("请输入知识库根地址");IPAddress ip;bool local=u.IsLoopback||u.Host.EndsWith(".local")||u.Host.EndsWith(".lan");if(IPAddress.TryParse(u.Host,out ip)&&ip.AddressFamily==System.Net.Sockets.AddressFamily.InterNetwork){byte[] b=ip.GetAddressBytes();local=local||b[0]==10||b[0]==192&&b[1]==168||b[0]==172&&b[1]>=16&&b[1]<=31;}if(u.Scheme=="http"&&!local)throw new Exception("公网地址请使用 HTTPS");return u.GetLeftPart(UriPartial.Authority);}
 static void Configure(string origin,string token){Origin=Normalize(origin);if(!System.Text.RegularExpressions.Regex.IsMatch(token,"^zn_[a-f0-9]{64}$"))throw new Exception("API 密钥格式不正确");var d=new Dictionary<string,object>();d["origin"]=Origin;d["token"]=Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(token),Entropy,DataProtectionScope.CurrentUser));d["collection"]="";Write(ConfigPath,d);}
 static void Load(){var d=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(ConfigPath));Origin=Normalize(S(d,"origin"));Token=Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(S(d,"token")),Entropy,DataProtectionScope.CurrentUser));Last=S(d,"collection");}
 internal static void Remember(string id){var d=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(ConfigPath));d["collection"]=id;Write(ConfigPath,d);Last=id;}
 static void Register(bool remove){string exe=System.Reflection.Assembly.GetExecutingAssembly().Location;foreach(string key in Keys){if(remove){using(var existing=Registry.CurrentUser.OpenSubKey(key+@"\command")){if(existing!=null&&!Convert.ToString(existing.GetValue("")).StartsWith("\""+exe+"\" ",StringComparison.OrdinalIgnoreCase))throw new Exception("菜单属于其他安装目录，未移除");}Registry.CurrentUser.DeleteSubKeyTree(key,false);}else{using(var k=Registry.CurrentUser.CreateSubKey(key)){k.SetValue("MUIVerb",key.Contains("SystemFileAssociations")?"保存到 ZNote":"保存剪贴板图片到 ZNote");k.SetValue("Icon",exe);k.SetValue("MultiSelectModel","Single");}using(var command=Registry.CurrentUser.CreateSubKey(key+@"\command"))command.SetValue("","\""+exe+"\""+(key.Contains("SystemFileAssociations")?" --file \"%1\"":" --clipboard"));}}}
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();try{
  if(args.Length>0&&args[0]=="--validate-config"){Load();return;}
  if(args.Length>0&&args[0]=="--install"){Load();Register(false);return;}
  if(args.Length>0&&args[0]=="--uninstall"){Register(true);return;}
  if(args.Length==2&&args[0]=="--configure-from"){var d=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(args[1]));Configure(S(d,"local_origin"),S(d,"local_token"));return;}
  if(!File.Exists(ConfigPath)||args.Contains("--configure")){Application.Run(new Connection());return;}
  Load();Application.Run(new Capture(args.Length==2&&args[0]=="--file"?args[1]:null));
 }catch(Exception e){if(args.Length>0&&new[]{"--install","--uninstall","--configure-from","--validate-config"}.Contains(args[0]))Console.Error.WriteLine(e.Message);else MessageBox.Show(e.Message,"ZNote 采集",MessageBoxButtons.OK,MessageBoxIcon.Warning);Environment.ExitCode=1;}}
 class Connection:Form {
  TextBox address=new TextBox(),key=new TextBox();Label state=new Label();
  internal Connection(){Icon=Icon.ExtractAssociatedIcon(System.Reflection.Assembly.GetExecutingAssembly().Location);Text="连接 ZNote 系统采集";ClientSize=new Size(430,260);StartPosition=FormStartPosition.CenterScreen;var layout=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(20)};Controls.Add(layout);layout.Controls.Add(new Label{Text="知识库地址",AutoSize=true});address.Width=370;address.Text="http://127.0.0.1:3741";layout.Controls.Add(address);layout.Controls.Add(new Label{Text="API 密钥（知识库的设置与连接中生成）",AutoSize=true});key.Width=370;key.UseSystemPasswordChar=true;layout.Controls.Add(key);var save=new Button{Text="保存连接并启用右键菜单",Width=370,Height=40};layout.Controls.Add(save);state.AutoSize=true;layout.Controls.Add(state);save.Click+=(s,e)=>{try{Configure(address.Text.Trim(),key.Text.Trim());Register(false);Close();}catch(Exception ex){state.Text=ex.Message;}};}
 }
 internal class Choice{internal string Id,Name;public override string ToString(){return Name;}}
 class Capture:Form {
  ComboBox libraries=new ComboBox();Button refresh=new Button(),save=new Button();Label state=new Label(),name=new Label();PictureBox preview=new PictureBox();byte[] clipboardImage;string file;bool saving,refreshing;string cachePath=Path.Combine(Home,"libraries.json");
  internal Capture(string path){Icon=Icon.ExtractAssociatedIcon(System.Reflection.Assembly.GetExecutingAssembly().Location);Text="保存到 ZNote";Font=new Font("Microsoft YaHei UI",10);ClientSize=new Size(450,510);MinimumSize=new Size(430,530);StartPosition=FormStartPosition.CenterScreen;AutoScaleMode=AutoScaleMode.Dpi;
   var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(20),RowCount=6,ColumnCount=1};root.RowStyles.Add(new RowStyle(SizeType.Absolute,220));root.RowStyles.Add(new RowStyle(SizeType.Absolute,38));root.RowStyles.Add(new RowStyle(SizeType.Absolute,30));root.RowStyles.Add(new RowStyle(SizeType.Absolute,44));root.RowStyles.Add(new RowStyle(SizeType.Absolute,50));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(root);
   preview.Dock=DockStyle.Fill;preview.SizeMode=PictureBoxSizeMode.Zoom;preview.BackColor=Color.FromArgb(240,242,246);root.Controls.Add(preview);name.Dock=DockStyle.Fill;name.AutoEllipsis=true;root.Controls.Add(name);root.Controls.Add(new Label{Text="目标知识库",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft});var picker=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};picker.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));picker.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,64));libraries.DropDownStyle=ComboBoxStyle.DropDownList;libraries.Dock=DockStyle.Fill;libraries.AccessibleName="目标知识库";refresh.Text="刷新";refresh.Dock=DockStyle.Fill;refresh.AccessibleName="刷新知识库";picker.Controls.Add(libraries);picker.Controls.Add(refresh);root.Controls.Add(picker);save.Text="保存到知识库";save.Dock=DockStyle.Fill;root.Controls.Add(save);state.Dock=DockStyle.Fill;state.AutoEllipsis=true;root.Controls.Add(state);
   libraries.Items.Add(new Choice{Id="",Name="未分类"});libraries.SelectedIndex=0;try{var cached=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(cachePath));if(S(cached,"origin")==Origin)Populate(cached["rows"]);}catch{}Select(Last);
   try{if(path!=null){file=Path.GetFullPath(path);if(!File.Exists(file)||new FileInfo(file).Length>100L*1024*1024||!new[]{".png",".jpg",".jpeg",".gif",".webp",".bmp",".tif",".tiff",".avif",".psd"}.Contains(Path.GetExtension(file).ToLowerInvariant()))throw new Exception("请选择不超过 100 MB 的图片文件");using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read))try{using(var img=Image.FromStream(input))preview.Image=new Bitmap(img);}catch{}name.Text=Path.GetFileName(file);}else{using(var image=Clipboard.GetImage()){if(image==null)throw new Exception("剪贴板没有图片。请先在聊天软件中复制图片，再使用此入口。");using(var stream=new MemoryStream()){image.Save(stream,System.Drawing.Imaging.ImageFormat.Png);clipboardImage=stream.ToArray();if(clipboardImage.Length>100L*1024*1024)throw new Exception("图片超过 100 MB");}preview.Image=new Bitmap(image);}name.Text="剪贴板图片";}}catch(Exception e){state.Text=e.Message;save.Enabled=false;}
   refresh.Click+=async(s,e)=>await RefreshList();save.Click+=async(s,e)=>await Save();Shown+=async(s,e)=>{if(libraries.Items.Count==1)await RefreshList();};FormClosed+=(s,e)=>{if(preview.Image!=null)preview.Image.Dispose();};
  }
  HttpClient Client(int seconds){var h=new HttpClientHandler{AllowAutoRedirect=false};if(new Uri(Origin).Scheme=="http")h.UseProxy=false;var c=new HttpClient(h){Timeout=TimeSpan.FromSeconds(seconds)};c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",Token);return c;}
  void Select(string id){for(int i=0;i<libraries.Items.Count;i++)if(((Choice)libraries.Items[i]).Id==id){libraries.SelectedIndex=i;return;}if(id!=""){libraries.Items.Add(new Choice{Id=id,Name="上次选择（请刷新确认）"});libraries.SelectedIndex=libraries.Items.Count-1;}}
  void Populate(object rows){string selected=libraries.SelectedItem==null?Last:((Choice)libraries.SelectedItem).Id;var items=new List<Choice>{new Choice{Id="",Name="未分类"}};foreach(var item in (IEnumerable)rows){var d=(Dictionary<string,object>)item;string id=S(d,"id"),n=S(d,"name");if(id!=""&&n!=""&&!items.Any(x=>x.Id==id))items.Add(new Choice{Id=id,Name=n});}libraries.Items.Clear();libraries.Items.AddRange(items.ToArray());Select(selected);if(libraries.SelectedIndex<0)libraries.SelectedIndex=0;}
  async System.Threading.Tasks.Task RefreshList(){if(refreshing)return;refreshing=true;refresh.Enabled=false;if(!saving)state.Text="正在刷新，仍可选库保存";try{using(var c=Client(8))using(var r=await c.GetAsync(Origin+"/api/collections")){string text=await r.Content.ReadAsStringAsync();if(!r.IsSuccessStatusCode)throw new Exception(r.StatusCode==HttpStatusCode.Unauthorized?"请在连接设置中更新 API 密钥":"刷新失败，已保留原选项");object data=Json.DeserializeObject(text);object rows=data is Dictionary<string,object>?((Dictionary<string,object>)data)["collections"]:data;if(IsDisposed)return;Populate(rows);Write(cachePath,new Dictionary<string,object>{{"origin",Origin},{"rows",rows}});if(!saving)state.Text="知识库列表已更新";}}catch(Exception e){if(!IsDisposed&&!saving)state.Text=e is System.Threading.Tasks.TaskCanceledException?"刷新超时，原选项仍可使用":e.Message;}finally{if(!IsDisposed){refreshing=false;refresh.Enabled=true;}}}
  async System.Threading.Tasks.Task Save(){if(saving)return;saving=true;save.Enabled=false;libraries.Enabled=false;string target=((Choice)libraries.SelectedItem).Id;state.Text="正在保存…";try{Remember(target);using(var c=Client(90))using(var body=new MultipartFormDataContent()){HttpContent content=file==null?(HttpContent)new ByteArrayContent(clipboardImage):new StreamContent(new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read));content.Headers.ContentType=new MediaTypeHeaderValue(file==null?"image/png":"application/octet-stream");body.Add(content,"file",file==null?"剪贴板图片.png":Path.GetFileName(file));body.Add(new StringContent("[]"),"tags");if(target!="")body.Add(new StringContent(target),"collection_id");using(var r=await c.PostAsync(Origin+"/api/assets",body)){string text=await r.Content.ReadAsStringAsync();if(!r.IsSuccessStatusCode){string error="保存失败（HTTP "+(int)r.StatusCode+"）";try{error=S(Json.Deserialize<Dictionary<string,object>>(text),"error");}catch{}throw new Exception(error);}if(!IsDisposed){state.Text="已保存到 ZNote";save.Text="已保存";}}}}catch(Exception e){if(!IsDisposed){state.Text="未确认保存，请重试："+(e is System.Threading.Tasks.TaskCanceledException?"网络超时":e.Message);save.Text="重试保存";save.Enabled=true;}}finally{saving=false;if(!IsDisposed)libraries.Enabled=true;}}
 }
